n  // Register a new panel (view) in SQL Lab and use shared UI components in your extension's React code\n  const panelDisposable = core.registerView('my_extension.panel', <MyPanel><Button/></MyPanel>);\n\n  // Register a custom command\n  const commandDisposable = commands.registerCommand('my_extension.copy_query', {\n    title: 'Copy Query',\n    execute: () => {\n      // Command logic here\n    },\n  });\n\n  // Listen for query run events in SQL Lab\n  const eventDisposable = sqlLab.onDidQueryRun(editor => {\n    // Handle query execution event\n  });\n\n  // Access a CSRF token for secure API requests\n  authentication.getCSRFToken().then(token => {\n    // Use token as needed\n  });\n\n  // Add all disposables for automatic cleanup on deactivation\n  context.subscriptions.push(panelDisposable, commandDisposable, eventDisposable);\n}\n"})}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Backend APIs"})," (via ",(0,a.jsx)(n.code,{children:"apache-superset-core"}),"):"]}),"\n",(0,a.jsx)(n.p,{children:"Backend APIs follow a similar pattern, providing access to Superset's models, sessions, and query capabilities. Extensions can register REST API endpoints, access the metadata database, and interact with Superset's core functionality."}),"\n",(0,a.jsxs)(n.p,{children:["Extension endpoints are registered under a dedicated ",(0,a.jsx)(n.code,{children:"/extensions"})," namespace to avoid conflicting with built-in endpoints and also because they don't share the same version constraints. By grouping all extension endpoints under ",(0,a.jsx)(n.code,{children:"/extensions"}),", Superset establishes a clear boundary between core and extension functionality, making it easier to manage, document, and secure both types of APIs."]}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{className:"language-python",children:'from superset_core.api.models import Database, get_session\nfrom superset_core.api.daos import DatabaseDAO\nfrom superset_core.api.rest_api import add_extension_api\nfrom .api import DatasetReferencesAPI\n\n# Register a new extension REST API\nadd_extension_api(DatasetReferencesAPI)\n\n# Fetch Superset entities via the DAO to apply base filters that filter out entities\n# that the user doesn\'t have access to\ndatabases = DatabaseDAO.find_all()\n\n# ..or apply simple filters on top of base filters\ndatabases = DatabaseDAO.filter_by(uuid=database.uuid)\nif not databases:\n    raise Exception("Database not found")\n\nreturn databases[0]\n\n# Perform complex queries using SQLAlchemy Query, also filtering out\n# inaccessible entities\nsession = get_session()\ndatabases_query = session.query(Database).filter(\n    Database.database_name.ilike("%abc%")\n)\nreturn DatabaseDAO.query(databases_query)\n\n# Bypass security model for highly custom use cases\nsession = get_session()\nall_databases_containing_abc = session.query(Database).filter(\n    Database.database_name.ilike("%abc%")\n).all()\n'})}),"\n",(0,a.jsx)(n.p,{children:"In the future, we plan to expand the backend APIs to support configuring security models, database engines, SQL Alchemy dialects, etc."})]})}function p(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},28453:(e,n,t)=>{t.d(n,{R:()=>i,x:()=>r});var s=t(96540);const a={},o=s.createContext(a);function i(e){const n=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),s.createElement(o.Provider,{value:n},e.children)}}}]);